package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import java.util.*;
final class DeliveryArchiveAcceptance {
 static final String API="/api/openservice/delivery/archive";
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> response,int status){assertEquals(status,response.statusCode(),html(response));return status==200?object(parsed(response).get("result")):parsed(response);}
 static Map<String,Object> post(WorkflowSupport h,Object body,int status)throws Exception{return result(h.json("POST",API,body,auth("admin")),status);}
 static Map<String,Object> page(WorkflowSupport h)throws Exception{return result(h.get(API,auth("admin")),200);}
 static Object revision(WorkflowSupport h)throws Exception{return object(page(h).get("policy")).get("revision");}
 static String seed(Store.Db db,String state,long expires)throws Exception{String job=DeliveryOperationsAcceptance.seed(db,state,1,0,expires);db.update("UPDATE os_outbox SET reference_id=? WHERE job_id=?","private-reference-"+job,job);return job;}
 static List<String> seed(WorkflowSupport h)throws Exception{try(var db=h.store.open()){db.update("UPDATE os_retention_policy SET days=90,revision=1");var ids=List.of(seed(db,"delivered",1),seed(db,"cancelled",2));db.connection.commit();return ids;}}
 static Map<String,Object> prepare(WorkflowSupport h)throws Exception{var review=object(post(h,map("operation","review"),200).get("review"));return map("operation","archive","cutoff",review.get("cutoff"),"proof",review.get("proof"),"key",id(),"confirm",true);}
 static Map<String,Object> restore(WorkflowSupport h,String batch)throws Exception{var review=object(post(h,map("operation","review_restore","batch_id",batch),200).get("review"));return map("operation","restore","batch_id",batch,"proof",review.get("proof"),"confirm",true);}
 static void journey(WorkflowSupport h)throws Exception{
  var ids=seed(h);post(h,map("operation","policy","revision",revision(h),"days",30),200);post(h,map("operation","hold","revision",revision(h),"job_id",ids.getLast(),"reason","Retain <script>evidence</script>"),200);var input=prepare(h);try(var db=h.store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_outbox"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_delivery_archive"));}var receipt=object(post(h,input,200).get("receipt"));assertEquals(1,receipt.get("item_count"));assertEquals(receipt,post(h,input,200).get("receipt"));assertFalse(receipt.toString().contains("private-reference"));try(var db=h.store.open()){assertNull(db.one("SELECT * FROM os_outbox WHERE job_id=?",ids.getFirst()));assertNotNull(db.one("SELECT * FROM os_outbox WHERE job_id=?",ids.getLast()));String envelope=db.one("SELECT envelope FROM os_delivery_archive").get("envelope").toString();assertFalse(envelope.contains(ids.getFirst()));assertFalse(envelope.contains("private-reference"));PlatformFoundationTest.bind(db);assertEquals(0,DeliveryRetention.run(db,db.viewerId,map("days",30,"confirm","PURGE"),true,System.currentTimeMillis()).get("deleted"));db.connection.commit();}
  String batch=input.get("key").toString();new Store(h.environment);var restore=restore(h,batch);Map<String,Object> restored;try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->post(h,restore,200));var b=pool.submit(()->post(h,restore,200));restored=object(a.get().get("receipt"));assertEquals(restored,b.get().get("receipt"));}assertEquals("restored",restored.get("state"));assertEquals(restored,post(h,restore,200).get("receipt"));assertEquals(restored,post(h,map("operation","review_restore","batch_id",batch),200).get("receipt"));try(var db=h.store.open()){var row=db.one("SELECT * FROM os_outbox WHERE job_id=?",ids.getFirst());assertEquals("delivered",row.get("state"));assertEquals("",row.get("envelope"));assertEquals("",row.get("lease"));assertNull(Outbox.claim(db,System.currentTimeMillis()));assertEquals("",db.one("SELECT envelope FROM os_delivery_archive").get("envelope"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_security_event WHERE action='delivery.metadata_archived'"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_security_event WHERE action='delivery.metadata_restored'"));}post(h,map("operation","release","revision",revision(h),"job_id",ids.getLast()),200);assertTrue(objects(page(h).get("holds")).isEmpty());
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=seed(h);try(var db=h.store.open()){seed(db,"delivered",100);assertEquals(2,DeliveryArchive.rows(db,100).size());assertEquals(3,DeliveryArchive.rows(db,101).size());db.connection.rollback();}h.account("ArchiveReader","reader");assertEquals(401,h.get(API,null).statusCode());assertEquals(403,h.get(API,auth("ArchiveReader")).statusCode());assertEquals(403,h.json("POST",API,map("operation","review"),auth("ArchiveReader")).statusCode());assertEquals(405,h.json("PUT",API,map(),auth("admin")).statusCode());assertEquals(400,h.get(API+"?x=1",auth("admin")).statusCode());assertEquals(403,h.form("/admin/delivery/archive",map("operation","review"),auth("admin")).statusCode());
  for(var bad:List.of(map(),map("operation","bad"),map("operation","review","extra",1),map("operation","policy","revision",1),map("operation","policy","revision",1,"days","030"),map("operation","policy","revision",1,"days",29),map("operation","policy","revision",1,"days",3651),map("operation","hold","revision",1,"job_id","bad","reason","x"),map("operation","hold","revision",1,"job_id",id(),"reason","x"),map("operation","hold","revision",1,"job_id",ids.getFirst(),"reason",""),map("operation","hold","revision",1,"job_id",ids.getFirst(),"reason","x".repeat(501)),map("operation","review_restore","batch_id","bad"),map("operation","review_restore","batch_id",id(),"extra",1)))post(h,bad,400);
  post(h,map("operation","release","revision",1,"job_id",id()),404);post(h,map("operation","review_restore","batch_id",id()),404);var good=prepare(h);for(var patch:List.of(map("confirm",false),map("key","bad"),map("cutoff","bad"),map("cutoff","999999999999999"),map("proof","bad"),map("extra",1))){var bad=new LinkedHashMap<>(good);bad.putAll(patch);post(h,bad,400);}post(h,good,200);var restore=restore(h,good.get("key").toString());var bad=new LinkedHashMap<>(restore);bad.put("confirm",false);post(h,bad,400);bad.put("confirm",true);bad.put("proof","wrong");post(h,bad,409);bad.put("extra",1);post(h,bad,400);post(h,restore,200);post(h,map("operation","policy","revision",revision(h),"days",3650),200);
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertThrows(Failure.class,()->DeliveryArchive.receipt(db,id()));db.update("DELETE FROM os_outbox");db.connection.commit();}var empty=prepare(h);post(h,empty,400);assertEquals(200,h.protectedForm("/admin/delivery/archive",map("operation","policy","revision",revision(h),"days","90"),auth("admin")).statusCode());
 }
 static void staleAndHolds(WorkflowSupport h)throws Exception{
  var ids=seed(h);var input=prepare(h);post(h,map("operation","hold","revision",revision(h),"job_id",ids.getLast(),"reason","Preserve"),200);post(h,input,409);post(h,map("operation","policy","revision",1,"days",90),409);post(h,map("operation","hold","revision",revision(h),"job_id",ids.getLast(),"reason","Updated reason"),200);assertEquals(1,objects(page(h).get("holds")).size());input=prepare(h);post(h,map("operation","release","revision",revision(h),"job_id",ids.getLast()),200);post(h,input,409);input=prepare(h);try(var db=h.store.open()){db.update("UPDATE os_outbox SET error='CHANGED' WHERE job_id=?",ids.getFirst());db.connection.commit();}post(h,input,409);input=prepare(h);try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE name='admin'");db.connection.commit();}post(h,input,409);input=prepare(h);post(h,input,200);var different=new LinkedHashMap<>(input);different.put("proof","0".repeat(64));post(h,different,409);
  var restore=restore(h,input.get("key").toString());try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE name='admin'");db.connection.commit();}post(h,restore,409);post(h,restore(h,input.get("key").toString()),200);
 }
 static void conflictsAndRollback(WorkflowSupport h)throws Exception{
  var ids=seed(h);var first=prepare(h);post(h,first,200);String batch=first.get("key").toString();var restore=restore(h,batch);String conflict;try(var db=h.store.open()){conflict=seed(db,"cancelled",3);db.update("UPDATE os_outbox SET kind='email.invitation',reference_id=? WHERE job_id=?","private-reference-"+ids.getLast(),conflict);db.connection.commit();}post(h,restore,409);try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_outbox"));db.update("DELETE FROM os_outbox");db.update("CREATE UNIQUE INDEX archive_restore_failure ON os_outbox(state)");db.connection.commit();}
  // Make both original states the same in an authenticated fixture envelope to force failure after the first INSERT.
  String original;try(var db=h.store.open()){var row=db.one("SELECT * FROM os_delivery_archive WHERE batch_id=?",batch);original=row.get("envelope").toString();var content=Outbox.decrypt(h.store.secret+":delivery-archive-v1",original);for(var item:objects(content.get("rows")))item.put("state","delivered");db.update("UPDATE os_delivery_archive SET envelope=? WHERE batch_id=?",Outbox.encrypt(h.store.secret+":delivery-archive-v1",JSON.writeValueAsString(content)),batch);db.connection.commit();}restore=restore(h,batch);post(h,restore,500);try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_outbox"));assertEquals("archived",db.one("SELECT state FROM os_delivery_archive").get("state"));db.update("DROP INDEX archive_restore_failure");db.update("UPDATE os_delivery_archive SET envelope=? WHERE batch_id=?",original,batch);db.connection.commit();}post(h,restore(h,batch),200);
  var next=prepare(h);try(var db=h.store.open()){db.update("CREATE UNIQUE INDEX archive_insert_failure ON os_security_event(action) WHERE action='delivery.metadata_archived'");db.connection.commit();}post(h,next,500);try(var db=h.store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_outbox"));db.update("DROP INDEX archive_insert_failure");db.connection.commit();}post(h,next,200);String second=next.get("key").toString();try(var db=h.store.open()){db.update("UPDATE os_delivery_archive SET envelope=? WHERE batch_id=?",original,second);db.connection.commit();}post(h,map("operation","review_restore","batch_id",second),409);try(var db=h.store.open()){db.update("UPDATE os_delivery_archive SET envelope='tampered' WHERE batch_id=?",second);db.connection.commit();}post(h,map("operation","review_restore","batch_id",second),500);try(var db=h.store.open()){db.update("ALTER TABLE os_delivery_archive RENAME TO archive_unavailable_fixture");db.connection.commit();}assertEquals(500,h.get(API,auth("admin")).statusCode());try(var db=h.store.open()){db.update("ALTER TABLE archive_unavailable_fixture RENAME TO os_delivery_archive");db.connection.commit();}
 }
 static void limitsAndConcurrency(WorkflowSupport h)throws Exception{
  seed(h);try(var db=h.store.open()){for(int n=0;n<99;n++)seed(db,"delivered",3);seed(db,"queued",1);seed(db,"failed",1);seed(db,"processing",1);seed(db,"delivered",Long.MAX_VALUE);db.connection.commit();}var input=prepare(h);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->post(h,input,200));var b=pool.submit(()->post(h,input,200));assertEquals(a.get().get("receipt"),b.get().get("receipt"));}assertEquals(100,object(post(h,input,200).get("receipt")).get("item_count"));try(var db=h.store.open()){assertEquals(5,db.count("SELECT COUNT(*) FROM os_outbox"));for(int n=0;n<1000;n++)db.update("INSERT INTO os_retention_hold(job_id,reason) VALUES(?,'fixture')",id());db.connection.commit();}String job;try(var db=h.store.open()){job=db.one("SELECT job_id FROM os_outbox WHERE state='delivered' AND expires_at=3").get("job_id").toString();}post(h,map("operation","hold","revision",revision(h),"job_id",job,"reason","Full"),400);
  var more=prepare(h);try(var db=h.store.open()){db.update("UPDATE os_delivery_archive SET item_count=5000");db.connection.commit();}post(h,more,400);try(var db=h.store.open()){db.update("UPDATE os_delivery_archive SET item_count=100");for(int n=0;n<999;n++)db.update("INSERT INTO os_delivery_archive(batch_id,state,created,item_count,fingerprint,envelope,detail) VALUES(?,'restored',?,0,'fixture','','{}')",id(),now());db.connection.commit();}post(h,more,400);
 }
}
